import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {execFileSync} from "node:child_process";
import {apply, planner} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";
import {projectCalendar, publicationCalendar} from "./utilization.mjs";

const date = "2025-04-02";
const nextDate = "2025-05-02";
const booking = (id, units, extra = {}) => ({
  service:"studio", action:"book", tenant:"orchid", day:date, id, units, ...extra
});

function tempDirectory(t) {
  const path = mkdtempSync(join(tmpdir(), "orchid-quota-"));
  t.after(() => rmSync(path, {recursive:true, force:true}));
  return path;
}

function cli(script, args, cwd) {
  return execFileSync(process.execPath, [fileURLToPath(new URL(script, import.meta.url)), ...args],
                      {cwd, encoding:"utf8"});
}

test("Studio allocations, defaults and tenant/day/desk accounting are independent", () => {
  const dispatch = planner({default:5, studios:new Map([["orchid", 8], ["iris", 2]])});
  assert.deepEqual(dispatch(booking("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(booking("second", 2)), {status:"full", id:"second", remaining:1});
  assert.equal(dispatch(booking("last", 1)).status, "booked");
  assert.equal(dispatch(booking("other-day", 8, {day:nextDate})).status, "booked");
  assert.equal(dispatch(booking("iris", 3, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(booking("unlisted", 5, {tenant:"rose"})).status, "booked");
  assert.equal(dispatch(booking("unlisted-full", 1, {tenant:"rose"})).status, "full");
  assert.equal(dispatch(booking("archive-full", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(booking("archive", 5, {service:"archive"})).status, "booked");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:date}), {units:8});
});

test("Studio identity and cancellation semantics precede capacity checks", () => {
  const dispatch = planner(readCatalog());
  const first = booking("first", 8);
  assert.equal(dispatch(first).status, "booked");
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch({...first, units:9}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:first.id}).status, "cancelled");
  assert.equal(dispatch(first).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:first.id}).status, "replay");
  assert.equal(dispatch(booking("replacement", 8)).status, "booked");
  assert.equal(apply(dispatch, booking("invalid", 0)).status, "invalid");
  const summary = dispatch({service:"studio", action:"summary"});
  assert.equal(summary.events.length, 3);
  assert.deepEqual(summary.occupied.map(row => row.id), ["replacement"]);
});

test("renewals use tenant allocations and preserve shared renewal semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(booking("previous", 7));
  dispatch(booking("already", 2, {day:nextDate}));
  const renewal = {service:"studio", action:"renew", previous:"previous", id:"renewed", day:nextDate};
  assert.deepEqual(dispatch(renewal), {status:"full", id:"renewed", remaining:6});
  dispatch({service:"studio", action:"cancel", id:"already"});
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"renewed", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  dispatch({service:"studio", action:"cancel", id:"renewed"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"previous"});
  assert.equal(dispatch({...renewal, id:"missing"}).status, "missing");

  dispatch(booking("rose", 5, {tenant:"rose"}));
  assert.equal(dispatch({...renewal, previous:"rose", id:"rose-next", units:6}).status, "full");
  assert.equal(dispatch({...renewal, previous:"rose", id:"rose-next"}).status, "booked");
});

test("imports retain bypass semantics and over-cap usage cannot admit new bookings", () => {
  const dispatch = planner(readCatalog());
  const imported = booking("backfill", 10, {action:"import"});
  assert.equal(dispatch(imported).status, "imported");
  assert.equal(dispatch({...imported, action:"book"}).status, "replay");
  assert.deepEqual(dispatch(booking("extra", 1)), {status:"full", id:"extra", remaining:0});
  const renewal = {service:"studio", action:"renew", previous:"backfill", id:"next", day:nextDate};
  assert.equal(dispatch(renewal).status, "full");
  assert.equal(dispatch({...renewal, units:8}).status, "booked");
});

function feed() {
  return {
    edition:"orchid-quota",
    window:{service:"studio", tenant:"orchid", from:date, through:"2025-04-03"},
    subscriptions:[{service:"studio", tenant:"orchid"}, {service:"studio", tenant:"iris"},
                   {service:"archive", tenant:"orchid"}],
    days:["2025-04-01", date, "2025-04-03", "2025-04-04"],
    operations:[
      booking("previous", 7, {day:"2025-04-01"}),
      {service:"studio", action:"renew", previous:"previous", id:"renewal", day:date},
      booking("cancelled", 2, {day:"2025-04-03"}),
      {service:"studio", action:"cancel", id:"cancelled"},
      booking("iris", 4, {tenant:"iris"}),
      booking("archive", 3, {service:"archive"})
    ]
  };
}

test("publication uses full replay but only includes the audience and inclusive window", () => {
  const source = feed();
  const original = structuredClone(source);
  assert.deepEqual(publicationCalendar(source, readCatalog()), [
    {service:"studio", tenant:"orchid", day:date, edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:0, available:8}
  ]);
  assert.deepEqual(source, original);
  assert.equal(projectCalendar(source, readCatalog()).length, 12);
  source.window.through = source.window.from;
  assert.equal(publicationCalendar(source, readCatalog()).length, 1);
});

test("invalid publication windows are rejected", () => {
  for (const window of [undefined, {}, {service:"other"},
    {service:"studio", tenant:"orchid", from:"2025-04-03", through:date},
    {service:"studio", tenant:"orchid", from:"2025-02-30", through:date}]) {
    assert.throws(() => publicationCalendar({...feed(), window}, readCatalog()));
  }
});

test("publish-calendar replaces only selected cells and is byte-for-byte idempotent", t => {
  const cwd = tempDirectory(t);
  const source = join(cwd, "feed.json");
  const destination = join(cwd, "diary.json");
  const preserved = [
    {service:"archive", tenant:"orchid", day:date, edition:"signed-spring", cap:5, used:1, available:4},
    {service:"studio", tenant:"orchid", day:"2025-04-01", edition:"signed-spring", cap:5, used:2, available:3},
    {service:"studio", tenant:"iris", day:"2025-04-03", edition:"signed-spring", cap:5, used:4, available:1}
  ];
  writeFileSync(source, JSON.stringify(feed()));
  writeFileSync(destination, JSON.stringify([...preserved,
    {service:"studio", tenant:"orchid", day:date, edition:"old", cap:5, used:0, available:5}]));
  const output = cli("./utilization.mjs", ["publish-calendar", source, destination], cwd);
  assert.deepEqual(JSON.parse(output), {edition:"orchid-quota", rows:2});
  const once = readFileSync(destination, "utf8");
  const rows = JSON.parse(once);
  assert.deepEqual(rows.slice(0, 3), preserved);
  assert.deepEqual(rows.slice(3), publicationCalendar(feed(), readCatalog()));
  cli("./utilization.mjs", ["publish-calendar", source, destination], cwd);
  assert.equal(readFileSync(destination, "utf8"), once);
});

test("stage queues only Studio, preserves other releases, and does not duplicate a release", t => {
  const cwd = tempDirectory(t);
  mkdirSync(join(cwd, "fixtures"));
  const queue = join(cwd, "fixtures/release-queue.json");
  const existing = {release:"summer", service:"archive", default:5, allocations:{}};
  writeFileSync(queue, JSON.stringify([existing]));
  cli("./replay.mjs", ["stage", "orchid-quota"], cwd);
  const once = readFileSync(queue, "utf8");
  const catalog = readCatalog();
  assert.deepEqual(JSON.parse(once), [existing, {release:"orchid-quota", service:"studio",
    default:catalog.default, allocations:Object.fromEntries(catalog.studios)}]);
  cli("./replay.mjs", ["stage", "orchid-quota"], cwd);
  assert.equal(readFileSync(queue, "utf8"), once);
});
EOF
cat >> README.md <<'EOF'

Studio admission uses the tenant's `studios` allocation, falling back to the
catalog default for unlisted tenants. Direct bookings and renewals share this
policy; imports remain unchecked backfills and Archive retains the default.

- `node replay.mjs stage <release>` queues the current Studio allocation in
  `fixtures/release-queue.json` without adding other desks or duplicating a release.
- `node utilization.mjs publish-calendar FEED DIARY` replays the complete feed,
  then upserts only subscribed cells whose desk and tenant match `window.service`
  and `window.tenant`, with dates from `window.from` through `window.through`
  (inclusive). Cells come from the feed's `days`, including unused days. Published
  rows carry the feed's `edition`; all other diary cells stay unchanged. Repeating
  the same publication is idempotent. `rebuild-calendar` still projects all cells.
EOF
